 "content": "def transform(grid):
    """Extend the seed triomino motif over every all-background occurrence."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The 8 seed's shape is: XX / ..X.  Find every matching occurrence
    # made entirely of background cells and recolor that occurrence 8.
    motif = ((0, 0), (0, 1), (1, 2))
    for r in range(h - 1):
        for c in range(w - 2):
            cells = [(r + dr, c + dc) for dr, dc in motif]
            if all(grid[rr][cc] == 0 for rr, cc in cells):
                for rr, cc in cells:
                    out[rr][cc] = 8
    return out
